CREATE TABLE payment_record (id BIGINT NOT NULL AUTO_INCREMENT,order_id BIGINT NOT NULL,provider VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,provider_reference VARCHAR(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,amount_minor BIGINT NOT NULL,idempotency_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,metadata JSON NOT NULL DEFAULT (JSON_OBJECT()),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),paid_payment TINYINT GENERATED ALWAYS AS(IF(status='paid',1,NULL)) STORED,PRIMARY KEY(id),CONSTRAINT uk_payment_record_reference UNIQUE(provider,provider_reference),CONSTRAINT uk_payment_record_idempotency UNIQUE(order_id,idempotency_key),CONSTRAINT uk_payment_record_one_paid UNIQUE(order_id,paid_payment),CONSTRAINT ck_payment_record_status CHECK(status IN ('paid','failed')),CONSTRAINT ck_payment_record_amount CHECK(amount_minor>=0),CONSTRAINT ck_payment_record_idempotency CHECK(REGEXP_LIKE(idempotency_key,'^[A-Za-z0-9._:-]{8,128}$','c')),CONSTRAINT fk_payment_record_order FOREIGN KEY(order_id) REFERENCES purchase_order(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
